import React from 'react'
import {
  Form,
  Input,
  Button,
  Divider,
} from 'antd'
import Myservice from '../services'

export default function Signup({
  history
}) {
  const [signupForm] = Form.useForm()

  async function submitForm(values){
    const {data} = await Myservice.signup({values})
    history.push("/login")
    console.log('user:', data)
  }

  return (
    <div>
        <Form layout='vertical' form={signupForm} onFinish={submitForm}>

          <Form.Item 
            name='name' 
            label='Email:'
            rules={[{required: true, message: 'Please input a valid email address'}]}
          >
            <Input />
          </Form.Item>

          <Form.Item 
            name='password' 
            label='Password:' 
            rules={[{required: true, message: 'Please input a password'}]}
          >
            <Input.Password />
          </Form.Item>

          <Button type="primary" block htmlType="submit">
            Signup
          </Button>

        </Form>
        <Divider>
          Or
        </Divider>
        <a href={'http://localhost:3000/auth/google/callback'}>
          <Button block>Signup with Google</Button>
        </a>
    </div>
  );
}
